using Elt = ORing::Elt;

double Now() { return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count(); }
double PeakRssGb() {
    struct rusage ru {};
    getrusage(RUSAGE_SELF, &ru);
    return static_cast<double>(ru.ru_maxrss) / (1024.0 * 1024.0);
}

struct Log {
    uint32_t checks = 0, failing = 0;
    std::map<std::string, uint32_t> per_arm;
    void check(const std::string& arm, bool ok, const std::string& what) {
        ++checks;
        ++per_arm[arm];
        if (!ok) {
            ++failing;
            std::cout << "  FAIL (" << arm << ") " << what << std::endl;
        }
    }
};

std::string Tag(uint32_t n, uint64_t ell) { return "(" + std::to_string(n) + "," + std::to_string(ell) + ")"; }
std::string SignName(int s) { return s < 0 ? "-" : "+"; }
Vec ModQ(const std::vector<uint64_t>& v, uint64_t q) {
    Vec o(v.size());
    for (size_t i = 0; i < v.size(); ++i) o[i] = v[i] % q;
    return o;
}
bool EqVec(const Elt& a, const std::vector<uint64_t>& b) { return a.size() == b.size() && std::equal(a.begin(), a.end(), b.begin()); }
uint32_t BallMismatches(const ORing& O, const std::vector<Elt>& x, const std::vector<Elt>& y) {
    uint32_t bad = 0;
    for (size_t a = 0; a < x.size(); ++a)
        if (x[a] != y[a]) ++bad;
    (void)O;
    return bad;
}
std::vector<uint32_t> Chars(uint64_t ell) {
    std::vector<uint32_t> c{0, 1, 2, static_cast<uint32_t>((ell - 1) / 2), static_cast<uint32_t>(ell - 2)};
    std::sort(c.begin(), c.end());
    c.erase(std::unique(c.begin(), c.end()), c.end());
    return c;
}

// one sign of one cell: the symbol, the identities, the frozen values, Galois; returns the measure (level M) when ordinary
struct SignOut {
    bool ok = false;
    OSymbolCell C;
    OMeasure me;
};

SignOut RunSign(const P3FrozenCell& fc, const P3FrozenSign* fs, int sign, uint32_t M, Log& log, bool galois) {
    SignOut out;
    const std::string st = Tag(fc.n, fc.ell) + " sign " + SignName(sign);
    const Vec gbar(fc.gbar.begin(), fc.gbar.end());
    const double t0 = Now();
    OSymbolCell C = RunOSymbolCell(fc.n, fc.ell, fc.R, gbar, fc.e, sign);
    log.check("R1", C.refusal.empty(), st + ": refused: " + C.refusal);
    if (!C.refusal.empty()) return out;
    const ORing& O = C.O;
    log.check("R1", C.eigen_all, st + ": T_p P == a_p P for p in {2,3,5,7,ell}");
    log.check("R1", C.a_p.at(2) == O.x(), st + ": a_2 == x (theta)");
    if (!fc.qexp_T2.empty())
        log.check("R1", O.is_zero(O.eval(ModQ(fc.qexp_T2, O.q()), C.a_p.at(2))), st + ": a_2 is a root of the q-expansion charpoly of T_2 | S_k");
    if (!fc.qexp_T3.empty())
        log.check("R1", O.is_zero(O.eval(ModQ(fc.qexp_T3, O.q()), C.a_p.at(3))), st + ": a_3 is a root of the q-expansion charpoly of T_3 | S_k");
    if (fs) {
        log.check("R1", C.t0 == fs->t0, st + ": t0 == frozen " + std::to_string(fs->t0));
        log.check("R1", EqVec(C.a_p.at(2), fs->a2) && EqVec(C.a_p.at(3), fs->a3) && EqVec(C.a_p.at(fc.ell), fs->a_ell),
                  st + ": a_2, a_3, a_ell == frozen (a_ell = " + O.str(C.a_p.at(fc.ell)) + ")");
        log.check("R1", C.ordinary == fs->ordinary, st + ": ordinarity == frozen");
    }
    std::cout << "P3_CELL cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " kind=" << fc.kind << " ring=" << O.name() << " e=" << fc.e
              << " dimW=" << C.dimW << " t0=" << C.t0 << " a_ell=" << O.str(C.a_p.at(fc.ell)) << " ordinary=" << (C.ordinary ? 1 : 0)
              << " symbol_secs=" << C.seconds << std::endl;
    if (!C.ordinary) {
        std::string why;
        try {
            (void)UnitRootO(O, C.a_p.at(fc.ell), fc.n + 2);
        } catch (const std::invalid_argument& ex) {
            why = ex.what();
        }
        log.check("R8", why.find("not ordinary") != std::string::npos, st + ": a non-ordinary cell must be refused by name (got '" + why + "')");
        std::cout << "P3_NEG cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " refusal='" << why << "'" << std::endl;
        out.C = C;
        return out;
    }
    if (fs) log.check("R1", EqVec(C.alpha, fs->alpha), st + ": alpha == frozen");
    const birch::SymRho rho(fc.n, O.base());
    const OMeasure me = BuildOMeasure(rho, O, C.P, C.a_p.at(fc.ell), C.alpha, M);
    // (R2) prop:lvmtt over O
    uint32_t tt = 0, df = 0;
    for (uint32_t m = 0; m + 1 <= M; ++m) {
        tt += ThreeTermFailuresO(me, m);
        df += DistributionFailuresO(me, m);
    }
    log.check("R2", tt == 0, st + ": three-term failures " + std::to_string(tt));
    log.check("R2", df == 0, st + ": distribution failures " + std::to_string(df));
    const auto mf = MomentFailuresO(rho, me, C.P, Chars(fc.ell));
    log.check("R2", mf.first == 0 && mf.second > 0, st + ": moment identity failures " + std::to_string(mf.first) + " / " + std::to_string(mf.second));
    const Elt tot = me.unit_total(M);
    if (sign < 0) log.check("R2", O.is_zero(tot), st + ": mu^{geo-odd}(Z_ell^x) == 0");
    std::cout << "P3_ID cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " M=" << M << " three_term=" << tt << " distribution=" << df
              << " moments=" << mf.first << "/" << mf.second << " mu(Z_l^x)=" << O.str(tot) << " secs=" << (Now() - t0) << std::endl;
    // (R3) the frozen measure
    if (fs && M >= 2) {
        const bool m2 = EqVec(me.mu[2][2], fs->mu2), ut = EqVec(me.unit_total(2), fs->units_total);
        const uint64_t f1 = me.fnv_units(2), f2 = me.fnv_trace_norm(2);
        log.check("R3", m2, st + ": mu(2 + ell^2) == frozen (got " + O.str(me.mu[2][2]) + ")");
        log.check("R3", ut, st + ": mu(Z_ell^x) == frozen");
        log.check("R3", f1 == fs->fnv, st + ": fnv_units(2) == frozen");
        log.check("R3", f2 == fs->fnv_trnorm, st + ": fnv_trace_norm(2) == frozen");
        std::ostringstream h;
        h << std::hex << "0x" << f1 << " fnv_trnorm=0x" << f2;
        std::cout << "P3_FROZEN cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " mu(2+l^2)=" << O.str(me.mu[2][2]) << " fnv=" << h.str()
                  << " match=" << ((m2 && ut && f1 == fs->fnv && f2 == fs->fnv_trnorm) ? 1 : 0) << std::endl;
    }
    // (R8) negatives: no ell^{k-2}, wrong root
    if (M >= 2) {
        const OMeasure mn = BuildOMeasure(rho, O, C.P, C.a_p.at(fc.ell), C.alpha, 2, false);
        const OMeasure mw = BuildOMeasure(rho, O, C.P, C.a_p.at(fc.ell), O.mul(C.alpha, O.scalar(1 + fc.ell)), 2, true);
        const uint32_t dn = DistributionFailuresO(mn, 1), dw = DistributionFailuresO(mw, 1);
        log.check("R8", dn > 0, st + ": NEG without ell^{k-2} must fail the distribution at m = 1");
        log.check("R8", dw > 0, st + ": NEG wrong root alpha(1+ell) must fail the distribution at m = 1");
        std::cout << "P3_NEG cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " no_ell_n_distribution_failures=" << dn
                  << " wrong_root_distribution_failures=" << dw << std::endl;
    }
    // (R4) Galois: the conjugate symbol recomputed
    if (galois) {
        const uint32_t L = std::min<uint32_t>(M, 2);
        const Elt sx = GaloisGenerator(O, fc.e);
        const Elt xx = O.x();
        const Elt stheta = O.eval(Vec(xx.begin(), xx.end()), sx);
        const OSymbolCell Cs = RunOSymbolCellIn(fc.n, O, stheta, sign);
        bool ok = Cs.refusal.empty() && Cs.ordinary;
        uint32_t mism = 0, neg = 0;
        bool symb = false, alph = false;
        if (ok) {
            symb = Cs.t0 == C.t0 && ApplySigma(O, sx, C.P) == Cs.P;
            alph = ApplySigma(O, sx, {C.alpha})[0] == Cs.alpha;
            const OMeasure ms = BuildOMeasure(rho, O, Cs.P, Cs.a_p.at(fc.ell), Cs.alpha, L);
            mism = BallMismatches(O, ms.mu[L], ApplySigma(O, sx, me.mu[L]));
            neg = BallMismatches(O, ms.mu[L], me.mu[L]);
        }
        log.check("R4", ok && symb, st + ": sigma(P_theta) == P_{sigma theta} (same t0)");
        log.check("R4", ok && alph, st + ": sigma(alpha) == alpha_{sigma theta}");
        log.check("R4", ok && mism == 0, st + ": mu_{sigma theta} == sigma o mu_theta on every level-" + std::to_string(L) + " ball (" + std::to_string(mism) +
                                             " mismatching)");
        log.check("R8", ok && neg > 0, st + ": NEG mu_{sigma theta} against mu_theta (no sigma) must mismatch");
        std::cout << "P3_GAL cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " sigma(x)=" << O.str(sx) << " symbol=" << symb << " alpha=" << alph
                  << " ball_mismatches=" << mism << " NEG_without_sigma=" << neg << std::endl;
    }
    out.ok = true;
    out.C = std::move(C);
    out.me = me;
    return out;
}

// (R5) the ramified route B
void RunRouteB(const P3FrozenCell& fc, const P3FrozenSign* fs, const SignOut& A, int sign, Log& log) {
    const std::string st = Tag(fc.n, fc.ell) + " sign " + SignName(sign);
    const ORing& O = A.C.O;
    const uint64_t lambda0 = (fc.ell - fc.gbar[0] % fc.ell) % fc.ell;
    const double t0 = Now();
    const RouteBReading B = RouteBRead(fc.n, fc.ell, fc.R, lambda0, sign);
    log.check("R5", B.complete && B.orders == 1 && B.roots == 2 && B.e == 2,
              st + ": the reader finds one order with e = 2 and two roots (" + B.refusal + ")");
    if (!B.complete) return;
    const birch::SymRho rho(fc.n, O.base());
    uint32_t r = 0;
    for (const RouteBRoot& X : B.found) {
        const ORing& T = X.Opi;
        std::vector<Elt> phiP;
        for (const Elt& v : A.C.P) phiP.push_back(PhiRho(O, X, lambda0, v));
        const bool symb = X.t0 == A.C.t0 && phiP == X.P;
        // a_p, alpha, the measure in O_pi from route B's own symbol
        bool aps = true;
        for (uint64_t p : std::vector<uint64_t>{2, 3, 5, 7, fc.ell}) {
            const std::vector<Elt> img = HeckeTpO(rho, T, X.P, p);
            const Elt a = img[X.t0];
            for (uint32_t t = 0; t <= fc.n; ++t)
                if (img[t] != T.mul(a, X.P[t])) aps = false;
            if (a != PhiRho(O, X, lambda0, A.C.a_p.at(p))) aps = false;
        }
        const Elt aB = HeckeTpO(rho, T, X.P, fc.ell)[X.t0];
        const Elt alB = UnitRootO(T, aB, fc.n + 2);
        const bool alph = alB == PhiRho(O, X, lambda0, A.C.alpha);
        const uint32_t L = std::min<uint32_t>(A.me.M, 2);   // the heavy (22, 144169) cell runs at level 1
        const OMeasure mB = BuildOMeasure(rho, T, X.P, aB, alB, L);
        std::vector<Elt> phiMu;
        for (const Elt& v : A.me.mu[L]) phiMu.push_back(PhiRho(O, X, lambda0, v));
        const uint32_t mism = BallMismatches(T, mB.mu[L], phiMu);
        const bool tn = fs && L == 2 && mB.fnv_trace_norm(2) == fs->fnv_trnorm;
        log.check("R5", symb, st + " root " + std::to_string(r) + ": phi_rho(P_theta) == P_rho (route B, normalised; same t0)");
        log.check("R5", aps, st + " root " + std::to_string(r) + ": route B is T_p-eigen with a_p == phi_rho(a_p)");
        log.check("R5", alph, st + " root " + std::to_string(r) + ": alpha_B == phi_rho(alpha)");
        log.check("R5", mism == 0, st + " root " + std::to_string(r) + ": mu_B == phi_rho(mu_A) on every level-" + std::to_string(L) + " ball (" + std::to_string(mism) + " mismatching)");
        if (fs) log.check("R5", tn, st + " root " + std::to_string(r) + ": route B's fnv_trace_norm(2) == frozen (presentation-free)");
        std::cout << "P3_RAMB cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " root=" << r << " O_pi=" << T.name() << " rho=" << T.str(X.rho)
                  << " eigen_check_vpi=" << X.eigen_check << " block_rank=" << B.block_rank << " symbol=" << symb << " a_p=" << aps << " alpha=" << alph
                  << " ball_mismatches=" << mism << " trnorm=" << tn << " secs=" << (Now() - t0) << std::endl;
        ++r;
    }
}

// (R6) Hida control mod m: route A at each weight of one class, the same gbar; the scalar c in F_ell^x frozen
void RunHida(Log& log) {
    const uint64_t ell = 29;
    const Vec gbar{15, 22, 1};
    const uint32_t R = 3;
    std::map<std::pair<uint32_t, int>, std::vector<Elt>> mus;
    std::map<std::pair<uint32_t, int>, OSymbolCell> cells;
    std::vector<uint32_t> ns{22};
    for (const auto& h : P3FrozenHidaTable())
        if (std::find(ns.begin(), ns.end(), h.n) == ns.end()) ns.push_back(h.n);
    const double t0 = Now();
    for (uint32_t n : ns)
        for (int sign : {-1, 1}) {
            OSymbolCell C = RunOSymbolCell(n, ell, R, gbar, 1, sign);
            const std::string st = "Hida " + Tag(n, ell) + " sign " + SignName(sign);
            log.check("R6", C.refusal.empty() && C.eigen_all && C.ordinary, st + ": ordinary eigen-symbol over W(F_{29^2}) (" + C.refusal + ")");
            if (!C.refusal.empty() || !C.ordinary) return;
            const birch::SymRho rho(n, C.O.base());
            const OMeasure me = BuildOMeasure(rho, C.O, C.P, C.a_p.at(ell), C.alpha, 2);
            std::vector<Elt> u;
            for (uint64_t a = 1; a < me.mu[2].size(); ++a)
                if (a % ell) u.push_back(me.mu[2][a]);
            mus[{n, sign}] = u;
            cells[{n, sign}] = C;
        }
    auto residual = [&](const Elt& a) {
        Elt o(a.size());
        for (size_t i = 0; i < a.size(); ++i) o[i] = a[i] % ell;
        return o;
    };
    for (const auto& h : P3FrozenHidaTable()) {
        const std::string st = "Hida mu_" + std::to_string(h.n) + " vs mu_" + std::to_string(h.n0) + " sign " + SignName(h.sign);
        const auto& base = mus[{h.n0, h.sign}];
        const auto& v = mus[{h.n, h.sign}];
        const OSymbolCell& C0 = cells[{h.n0, h.sign}];
        const OSymbolCell& C1 = cells[{h.n, h.sign}];
        log.check("R6", residual(Elt(C0.O.F().begin(), C0.O.F().end())) == residual(Elt(C1.O.F().begin(), C1.O.F().end())),
                  st + ": F == gbar mod ell at both weights (one residual presentation)");
        log.check("R6", residual(C0.a_p.at(3)) == residual(C1.a_p.at(3)) && residual(C0.a_p.at(ell)) == residual(C1.a_p.at(ell)) &&
                            residual(C0.a_p.at(5)) == residual(C1.a_p.at(5)),
                  st + ": the residual eigen-system (a_3, a_5, a_ell mod m) is the same");
        uint32_t bad = 0;
        for (size_t i = 0; i < v.size(); ++i) {
            const Elt w = residual(C0.O.smul(h.c, base[i]));
            if (w != residual(v[i])) ++bad;
        }
        log.check("R6", bad == 0 && !v.empty(), st + ": mu_n == c mu_n0 mod m with the frozen c = " + std::to_string(h.c) + " (" + std::to_string(bad) + " mismatching)");
        std::cout << "P3_HIDA ell=29 n0=" << h.n0 << " n=" << h.n << " sign=" << SignName(h.sign) << " c=" << h.c << " mismatching=" << bad << "/" << v.size()
                  << std::endl;
    }
    // NEG: the conjugate measure sigma o mu_50 fits no scalar in F_ell^x against mu_22 (geometric odd)
    {
        const OSymbolCell& C1 = cells[{50, -1}];
        const Elt sx = GaloisGenerator(C1.O, 1);
        const std::vector<Elt> sv = ApplySigma(C1.O, sx, mus[{50, -1}]);
        const auto& base = mus[{22, -1}];
        uint32_t best = 0;
        for (uint64_t c = 1; c < ell; ++c) {
            uint32_t good = 0;
            for (size_t i = 0; i < sv.size(); ++i)
                if (residual(C1.O.smul(c, base[i])) == residual(sv[i])) ++good;
            best = std::max(best, good);
        }
        log.check("R8", best < sv.size(), "Hida NEG: sigma o mu_50 must fit no F_ell-scalar multiple of mu_22 (best " + std::to_string(best) + ")");
        std::cout << "P3_NEG hida_conjugate best_matching=" << best << "/" << sv.size() << " secs=" << (Now() - t0) << std::endl;
    }
}

// (R7) degree-1 controls against WP-MEAS's tables, and base change of Delta into W(F_{37^2})
void RunDegreeOne(const P3FrozenCell& fc, const SignOut& A, int sign, Log& log) {
    const std::string st = Tag(fc.n, fc.ell) + " sign " + SignName(sign);
    // R20-1's frozen values of record (WP-MEAS spec Sec. 2 (M2)), independent of P3's own frozen table
    const std::map<std::pair<uint32_t, int>, uint64_t> r201 = {{{10, -1}, 0x721edc172f8e24bdULL}, {{10, 1}, 0xcc0c00522e7e0429ULL},
                                                               {{16, -1}, 0xed8c569e28ac74beULL}, {{16, 1}, 0x57a02c809eb73309ULL}};
    const auto it = r201.find({fc.n, sign});
    log.check("R7", it != r201.end() && A.me.fnv_units(2) == it->second, st + ": fnv_units(2) == R20-1's frozen value (WP-MEAS (M2))");
    // WP-MEAS's own route: RunSymbolCell + BuildMeasure (normalised as here)
    const std::map<uint64_t, uint64_t> sep = {{2, 1}, {3, 3}, {5, 7}};
    const birch::SymbolCell S = birch::RunSymbolCell(fc.n, fc.ell, fc.R, sep, true);
    bool same = false;
    if (S.simple) {
        Vec P = sign < 0 ? S.r_minus : S.r_plus;
        uint32_t t = 0;
        while (t < P.size() && !S.ring.unit(P[t])) ++t;
        const uint64_t iv = S.ring.inv(P[t]);
        for (auto& v : P) v = S.ring.mul(v, iv);
        const birch::SymRho rho(fc.n, S.ring);
        const uint64_t al = birch::UnitRoot(S.ring, S.a_p.at(fc.ell), fc.n + 2);
        const ModularSymbolMeasure W = birch::BuildMeasure(rho, P, S.a_p.at(fc.ell), al, 2, true);
        same = true;
        for (uint32_t m = 0; m <= 2; ++m)
            for (size_t a = 0; a < W.mu[m].size(); ++a)
                if (A.me.mu[m][a][0] != W.mu[m][a]) same = false;
        for (uint32_t m = 0; m < 4; ++m)
            for (size_t a = 0; a < W.c[m].size(); ++a)
                if (A.me.c[m][a][0] != W.c[m][a]) same = false;
    }
    log.check("R7", same, st + ": c- and mu-tables == WP-MEAS's BuildMeasure(RunSymbolCell r^" + SignName(sign) + ") entry by entry");
    // base change into O' = (Z/37^4)[x]/(x^2 - 2)
    const ORing& O1 = A.C.O;
    const ORing O2(fc.ell, fc.R, Vec{O1.base().neg(2), 0, 1});
    auto embed = [&](const Elt& a) {
        Elt o = O2.zero();
        o[0] = a[0];
        return o;
    };
    bool bc = false;
    uint32_t mism = 0;
    if (O1.d() == 1) {
        std::vector<Elt> P2;
        for (const Elt& v : A.C.P) P2.push_back(embed(v));
        const Elt a2 = embed(A.C.a_p.at(fc.ell));
        const Elt al2 = UnitRootO(O2, a2, fc.n + 2);
        const birch::SymRho rho(fc.n, O2.base());
        const OMeasure m2 = BuildOMeasure(rho, O2, P2, a2, al2, 2);
        for (uint32_t m = 0; m <= 2; ++m)
            for (size_t a = 0; a < m2.mu[m].size(); ++a)
                if (m2.mu[m][a] != embed(A.me.mu[m][a])) ++mism;
        bc = al2 == embed(A.C.alpha) && mism == 0;
    }
    log.check("R7", bc, st + ": base change into " + O2.name() + ": alpha and every ball == the embedded values (" + std::to_string(mism) + " mismatching)");
    std::cout << "P3_BASE cell=" << Tag(fc.n, fc.ell) << " sign=" << SignName(sign) << " r201_fnv=" << (it != r201.end() && A.me.fnv_units(2) == it->second)
              << " wpmeas_tables=" << same << " base_change=" << bc << std::endl;
}

void RunCell(const P3FrozenCell& fc, Log& log, uint32_t M, bool frozen) {
    const std::string kind = fc.kind;
    const birch::Ring R = birch::MakeRing(fc.ell, fc.R);
    const double t0 = Now();
    // (R0) setup: Eichler-Shimura against the q-expansions, gbar, F
    OSymbolCell S0 = RunOSymbolCell(fc.n, fc.ell, fc.R, Vec(fc.gbar.begin(), fc.gbar.end()), fc.e, -1);
    const std::string st = Tag(fc.n, fc.ell);
    log.check("R0", S0.refusal.empty(), st + ": setup refused: " + S0.refusal);
    if (!S0.refusal.empty()) return;
    if (!fc.qexp_T2.empty())
        log.check("R0", S0.chi_T2 == ModQ(fc.qexp_T2, R.q), st + ": charpoly(T_2 | W^-) == the q-expansion charpoly of T_2 | S_k mod ell^R");
    if (!fc.qexp_T3.empty())
        log.check("R0", S0.chi_T3 == ModQ(fc.qexp_T3, R.q), st + ": charpoly(T_3 | W^-) == the q-expansion charpoly of T_3 | S_k mod ell^R");
    const Vec gbar(fc.gbar.begin(), fc.gbar.end());
    log.check("R0", IrreducibleModEll(gbar, fc.ell) && MultiplicityModEll(S0.chi_T2, gbar, fc.ell) == fc.e,
              st + ": gbar irreducible mod ell with multiplicity e = " + std::to_string(fc.e));
    if (frozen) log.check("R0", S0.F == ModQ(fc.F, R.q), st + ": F == the frozen Hensel factor");
    std::cout << "P3_CELL cell=" << st << " kind=" << kind << " R=" << fc.R << " M=" << M << " ring=" << S0.O.name() << " setup_secs=" << (Now() - t0) << std::endl;
    std::map<int, SignOut> outs;
    const bool galois = kind == "unram" || kind == "ram";
    for (int sign : {-1, 1}) {
        const P3FrozenSign* fs = nullptr;
        if (frozen)
            for (const auto& s : fc.signs)
                if (s.sign == sign) fs = &s;
        outs[sign] = RunSign(fc, fs, sign, M, log, galois);
        if (!outs[sign].ok) continue;
        if (kind == "ram") RunRouteB(fc, fs, outs[sign], sign, log);
        if (kind == "Z" && frozen) RunDegreeOne(fc, outs[sign], sign, log);
    }
    if (outs[-1].ok && outs[1].ok) {
        bool same = true;
        for (const auto& kv : outs[-1].C.a_p)
            if (outs[1].C.a_p.at(kv.first) != kv.second) same = false;
        log.check("R1", same, st + ": a_p equal on both signs (Eichler-Shimura)");
    }
}

// (R8) refusals of the ring / the eliminator
void RunRefusals(Log& log) {
    auto refused = [&](const std::string& what, const std::string& want, const std::string& got) {
        log.check("R8", got.find(want) != std::string::npos, what + ": must be refused with '" + want + "' (got '" + got + "')");
        std::cout << "P3_NEG " << what << " refusal='" << got << "'" << std::endl;
    };
    {
        const OSymbolCell C = RunOSymbolCell(22, 23, 4, Vec{1, 0, 1}, 1, -1);   // x^2 + 1: irreducible mod 23, not a factor
        refused("(22,23) gbar=x^2+1", "does not divide", C.refusal);
    }
    {
        const OSymbolCell C = RunOSymbolCell(22, 23, 4, Vec{22, 0, 1}, 1, -1);  // x^2 - 1: reducible
        refused("(22,23) gbar=x^2-1", "not irreducible", C.refusal);
    }
    {
        const ORing O(23, 4, Vec{0, 1});   // Z/23^4 (x = 0)
        birch::Mat A(2, 2);
        A.at(0, 0) = 5;
        A.at(1, 1) = 5;
        std::string got;
        try {
            (void)KernelVectorLocal(O, A, O.scalar(5));
        } catch (const std::invalid_argument& ex) {
            got = ex.what();
        }
        refused("eliminator on 5 I_2 at theta = 5", "residual eigenspace of rank >= 2", got);
    }
}

