uint32_t HeckeLValueCoefficientRingValidation() {
    using namespace hecke_ext::lvalue;
    const double T0 = Now();
    Log log;
    const char* hv = std::getenv("HECKE_LVALUE_COEFFRING_HEAVY");
    const bool heavy = hv && std::string(hv) == "1";
    std::cout << "EFFECTIVE HeckeLValueCoefficientRingValidation arm=" << (heavy ? "HEAVY cells=2" : "DEFAULT cells=11") << std::endl;
    try {
        for (const P3FrozenCell& fc : P3Frozen()) RunCell(fc, log, fc.M, true);
        RunHida(log);
        RunRefusals(log);
        if (heavy) {
            // (22, 144169): S_24 at its ramified prime, R = 2, level 1 (no frozen values); (34, 37) at level 3
            const uint64_t L = 144169;
            const birch::Ring R2 = birch::MakeRing(L, 2);
            const Vec q2{R2.from_int(-20468736), R2.from_int(-1080), 1};
            // the double root of x^2 - 1080 x - 20468736 mod ell: 540
            P3FrozenCell h1{22, L, 2, 1, "ram", 2, {L - 540, 1}, {}, {q2[0], q2[1], 1}, {}, {}};
            RunCell(h1, log, 1, false);
            for (const P3FrozenCell& fc : P3Frozen())
                if (fc.n == 34 && fc.ell == 37) {
                    P3FrozenCell h2 = fc;
                    h2.kind = "unram-M3";
                    RunCell(h2, log, 3, false);
                }
        }
    } catch (const std::exception& e) {
        log.check("EXC", false, std::string("exception: ") + e.what());
    }
    std::ostringstream arms;
    for (const auto& kv : log.per_arm) arms << kv.first << "=" << kv.second << " ";
    std::cout << "P3_ARMS checks=" << log.checks << " failing=" << log.failing << " per_arm: " << arms.str() << "secs=" << (Now() - T0)
              << " peak_rss_gb=" << PeakRssGb() << std::endl;
    return log.failing == 0 ? 0u : 1u;
}
